package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.CertificateVO;

class CertificateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of certificate of tenant login provider")
  void test_certificate_value_holder_assign_plain_value() {
    Object holder = new Object();
    CertificateValueHolder<Object> value = new CertificateValueHolder<>(holder);
    Assertions.assertSame(holder, value.certificate("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getCertificateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getCertificate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.certificateNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getCertificateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getCertificate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of certificate of tenant login provider")
  void test_certificate_value_holder_assign_value_object() {
    Object holder = new Object();
    CertificateValueHolder<Object> value = new CertificateValueHolder<>(holder);
    CertificateVO vo = CertificateVO.from("one");
    Assertions.assertFalse(value.getCertificateValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.certificate(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getCertificateValue().orElseThrow());
    Assertions.assertSame(holder, value.certificate(Optional.empty()));
    Assertions.assertFalse(value.getCertificateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.certificate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getCertificateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of certificate of tenant login provider against the original")
  void test_certificate_value_holder_read() {
    Object holder = new Object();
    CertificateValueHolder<Object> value = new CertificateValueHolder<>(holder);
    CertificateVO vo = CertificateVO.from("one");
    CertificateVO other = CertificateVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getCertificateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readCertificate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readCertificate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.certificate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readCertificate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readCertificate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of certificate of tenant login provider")
  void test_certificate_value_holder_unset() {
    Object holder = new Object();
    CertificateValueHolder<Object> value = new CertificateValueHolder<>(holder);
    CertificateVO vo = CertificateVO.from("one");
    value.certificate(vo);
    Assertions.assertSame(holder, value.unsetCertificateIfMatches("certificate_other"));
    Assertions.assertTrue(value.getCertificateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetCertificateIfMatches("certificate"));
    Assertions.assertFalse(value.getCertificateValue().isPresent(),
        "The field name must clear the value");
    value.certificate(vo);
    Assertions.assertSame(holder, value.unsetCertificate());
    Assertions.assertFalse(value.getCertificateValue().isPresent(), "Unset must clear the value");
  }
}
